{
  "domain": "maenifold.workflow",
  "commands": [
    {
      "name": "DeleteWorkflowAsset",
      "description": "Deletes one workflow asset by name when no running pipeline references it.",
      "schema": {
        "additionalProperties": false,
        "title": "DeleteWorkflowAssetParams",
        "type": "object",
        "required": [
          "name"
        ],
        "properties": {
          "name": {
            "description": "Workflow asset name to delete. Must be a single kebab-case asset name without extension.",
            "type": "string"
          }
        }
      },
      "safety_class": "destructive"
    },
    {
      "name": "Pipeline",
      "description": "Creates and manages pipeline sessions composed of DAG nodes.",
      "schema": {
        "additionalProperties": false,
        "title": "PipelineParams",
        "type": "object",
        "properties": {
          "cancel": {
            "description": "Cancel a running pipeline and stop future execution",
            "default": false,
            "type": "boolean"
          },
          "conclusion": {
            "description": "Conclusion text when completing a node",
            "default": null,
            "type": "string"
          },
          "definition": {
            "description": "Pipeline definition with nodes[] and edges[]",
            "allOf": [
              {
                "type": "object",
                "required": [
                  "edges",
                  "nodes"
                ],
                "properties": {
                  "edges": {
                    "description": "Pipeline edges connecting nodes",
                    "type": "array",
                    "items": {
                      "type": "object",
                      "oneOf": [
                        {
                          "type": "object",
                          "required": [
                            "type"
                          ],
                          "properties": {
                            "type": {
                              "type": "string",
                              "enum": [
                                "success"
                              ]
                            }
                          }
                        },
                        {
                          "type": "object",
                          "required": [
                            "type"
                          ],
                          "properties": {
                            "type": {
                              "type": "string",
                              "enum": [
                                "always"
                              ]
                            }
                          }
                        },
                        {
                          "type": "object",
                          "required": [
                            "equals",
                            "path",
                            "type"
                          ],
                          "properties": {
                            "equals": {
                              "description": "Expected JSON value at `path`"
                            },
                            "path": {
                              "description": "JSON path within upstream output to inspect",
                              "type": "string"
                            },
                            "type": {
                              "type": "string",
                              "enum": [
                                "conditional"
                              ]
                            }
                          }
                        }
                      ],
                      "required": [
                        "source",
                        "target"
                      ],
                      "properties": {
                        "source": {
                          "description": "Upstream node identifier",
                          "type": "string"
                        },
                        "target": {
                          "description": "Downstream node identifier",
                          "type": "string"
                        }
                      }
                    }
                  },
                  "inputs": {
                    "description": "Optional pipeline inputs persisted with the definition and session",
                    "default": null,
                    "type": "object",
                    "additionalProperties": true
                  },
                  "nodes": {
                    "description": "Pipeline nodes to execute",
                    "type": "array",
                    "items": {
                      "oneOf": [
                        {
                          "description": "A workflow pipeline node",
                          "type": "object",
                          "required": [
                            "id",
                            "type",
                            "workflowId"
                          ],
                          "properties": {
                            "acpClient": {
                              "description": "Optional ACP client",
                              "type": "string"
                            },
                            "adopt": {
                              "description": "Per-node adoption configuration applied before prompt dispatch",
                              "type": "object",
                              "properties": {
                                "color": {
                                  "description": "Optional color asset identifier to adopt",
                                  "type": "string"
                                },
                                "perspective": {
                                  "description": "Optional perspective asset identifier to adopt",
                                  "type": "string"
                                },
                                "role": {
                                  "description": "Optional role asset identifier to adopt",
                                  "type": "string"
                                }
                              },
                              "additionalProperties": false
                            },
                            "cwd": {
                              "description": "Optional working directory for this node",
                              "type": "string"
                            },
                            "displayLabel": {
                              "description": "Optional presentation-only label for UI surfaces",
                              "type": "string"
                            },
                            "id": {
                              "description": "New node identifier",
                              "type": "string"
                            },
                            "joinPolicy": {
                              "description": "Fan-in join policy. 'all' (default) waits for every inbound predecessor; 'any' fires when at least one completes and the rest are terminal; 'first' fires as soon as any completes.",
                              "type": "string",
                              "enum": [
                                "all",
                                "any",
                                "first"
                              ]
                            },
